records.rawDisplayText:
这是我当前的config.alloy的配置：log_level = "debug"

// ============================
// Docker 容器日志采集
// ============================

// 发现本机所有 Docker 容器
discovery.docker "local" {
  host = "unix:///var/run/docker.sock"
}

// 从容器名中提取标签
discovery.relabel "docker_labels" {
  targets = []

  rule {
    source_labels = ["__meta_docker_container_name"]
    regex         = "/(.*)"
    target_label  = "container_name"
  }

  rule {
    target_label = "instance"
    replacement  = constants.hostname
  }
}

// 采集容器 stdout/stderr 日志
loki.source.docker "containers" {
  host          = "unix:///var/run/docker.sock"
  targets       = discovery.docker.local.targets
  relabel_rules = discovery.relabel.docker_labels.rules
  forward_to    = [loki.process.docker_logs.receiver]
}

// 处理 Docker 日志：给所有容器日志打 job 标签
loki.process "docker_logs" {
  forward_to = [loki.write.local.receiver]

  stage.static_labels {
    values = {
      job = "docker",
    }
  }
}

// ============================
// 系统日志采集
// ============================

// 匹配系统日志文件
local.file_match "syslog" {
  path_targets = [
    {"__path__" = "/var/log/syslog",   "job" = "syslog",  "host" = "docker-host"},
    {"__path__" = "/var/log/auth.log", "job" = "authlog", "host" = "docker-host"},
  ]
  sync_period = "5s"
}

// 采集系统日志文件
loki.source.file "syslog" {
  targets       = local.file_match.syslog.targets
  forward_to    = [loki.write.local.receiver]
  tail_from_end = true
}

// ============================
// 写入 Loki
// ============================

loki.write "local" {
  endpoint {
    url = "http://loki:3100/loki/api/v1/push"
  }
}

